}
struct VCSCanPushKey: FocusedValueKey {
  typealias Value = Bool
}
struct VCSCanPullKey: FocusedValueKey {
  typealias Value = Bool
}

/// Whether any run terminal exists to jump to (issue #7) — published by RootView, so the
