/// Menu-bar commands + keyboard shortcuts. They act on the shared store so they work
/// regardless of which pane has focus.
struct WorkroomCommands: Commands {
  @ObservedObject var updater: Updater
  /// The focused window's store (issue #70). Optional — nil when no Workroom window is key, in which
  /// case actions no-op and toggle bindings read false.
  ///
  /// It does **NOT** go nil merely because a dialog is up, contrary to what this comment used to
  /// claim: verified on the real build, with the Add Project sheet attached every File-menu item still
  /// read `enabled=true` and ⌘T created a second terminal tab behind it. That is why enablement has to
  /// AND in `AppStore.hasModalPresentation` explicitly (see `modalBlocked` and `MenuStateValues`).
  /// `@FocusedObject`
  /// re-evaluates this `Commands` body when the focused store changes, so checkmarks like Projects
  /// track the focused window's `sidebarVisible` live (the role the old `@ObservedObject` played).
  @FocusedObject private var store: AppStore?
  @FocusedValue(\.workroomSelected) private var workroomSelected
  @FocusedValue(\.hasTerminal) private var hasTerminal
  @FocusedValue(\.hasNotifications) private var hasNotifications
  @FocusedValue(\.hasProjects) private var hasProjects
  @FocusedValue(\.canNavigateBack) private var canNavigateBack
  @FocusedValue(\.canNavigateForward) private var canNavigateForward
  @FocusedValue(\.hasRunCommand) private var hasRunCommand
  @FocusedValue(\.runCommandActive) private var runCommandActive
  @FocusedValue(\.vcsCanFetch) private var vcsCanFetch
  @FocusedValue(\.vcsCanPush) private var vcsCanPush
  @FocusedValue(\.vcsCanPull) private var vcsCanPull
  @FocusedValue(\.hasRunTerminal) private var hasRunTerminal
  @FocusedValue(\.multipleTerminalTabs) private var multipleTerminalTabs
  @FocusedValue(\.multipleWorkroomTabs) private var multipleWorkroomTabs
  @FocusedValue(\.canSwitchWorkrooms) private var canSwitchWorkrooms
  @FocusedValue(\.canOpenInEditor) private var canOpenInEditor
  @FocusedValue(\.terminalSplitVisible) private var terminalSplitVisible
  @FocusedValue(\.workroomSplitVisible) private var workroomSplitVisible
  @FocusedValue(\.modalPresented) private var modalPresented
  // Shared with RootView's inspector + toolbar toggle (same key) so all three stay in sync.
  @Default(.showInspector) private var showInspector
  // Same key as the Settings checkbox so the two stay in sync; GhosttySurfaceView reads it
  // on each selection, so toggling here takes effect on the next drag.
  @Default(.copyOnSelect) private var copyOnSelect
  // Gate the quit-confirmation alert. Same key as the Settings checkbox so the two stay in sync;
  // AppDelegate reads it in applicationShouldTerminate.
  @Default(.confirmOnQuit) private var confirmOnQuit
  // Gate the close-terminal confirmation (default on). Same key as the Settings checkbox and the
  // dialog's "Don't ask me again", so the File-menu checkmark reflects — and drives — all three;
  // AppStore reads it in requestCloseTerminalTab.
  @Default(.confirmOnCloseTerminal) private var confirmOnCloseTerminal
  // Drives the quick dark/light toggle (⌘⇧L, issue #57). RootView's `.onChange(of: theme)` applies
  // it through the single theme chokepoint; same key as the sidebar's 3-state cycle button.
  @Default(.theme) private var theme
  // The two quick-switcher trigger chords (issue #132). Read here so the Go-menu items re-render — and
  // so their key equivalents follow the preference — when either is retuned in Settings.
  @Default(.switcherWorkroomModifier) private var switcherWorkroomModifier
  @Default(.switcherPaneModifier) private var switcherPaneModifier
  /// Opens a new Workroom window (issue #70) — a fresh `WindowSeed` so the window starts blank.
  @Environment(\.openWindow) private var openWindow

  /// A `Binding<Bool>` onto a `Bool` property of the focused store — reads false and ignores writes
  /// when no window is focused (issue #70). Backs the menu toggles that drive per-window state.
  /// True while a modal presentation owns the focused window. Items whose enablement flows through a
  /// `MenuStateValues` boolean already have this ANDed in at the publication site; the ones below have
  /// no such boolean (the `@Default`-bound View-menu toggles, and Quick Terminal, which is documented
  /// "always enabled"), so they AND it in here. Without this their key equivalents fire straight
  /// through a dialog — verified: ⌘T behind the Add Project sheet really did open a terminal tab.
  private var modalBlocked: Bool { modalPresented == true }

  private func storeFlag(_ keyPath: ReferenceWritableKeyPath<AppStore, Bool>) -> Binding<Bool> {
    Binding(
      get: { store?[keyPath: keyPath] ?? false },
      set: { store?[keyPath: keyPath] = $0 })
  }

  var body: some Commands {
    CommandGroup(after: .appInfo) {
      // Sparkle update check, sitting directly beneath "About Workroom". Disabled while a check is
      // already running. See Core/Updater.swift.
      Button("Check for Updates…") { updater.checkForUpdates() }
        .disabled(!updater.canCheckForUpdates)
    }

    // App menu: the "Install workroom Command" + "Keyboard Shortcuts…" items, sitting just below
    // Settings… and above Services. Anchored `before: .systemServices`, NOT `after: .appSettings`:
    // the `Settings` scene injects the "Settings…" item at the END of the appSettings group, so
    // `after: .appSettings` lands ABOVE Settings… — anchoring before Services is the documented way
    // to sit just below it. Keyboard Shortcuts has no accelerator (a ⌘-key would need reserving from
    // the terminal in GhosttySurfaceView.isAppShortcut; the menu item is discovery enough) and posts
    // a notification RootView observes to present the sheet (a menu command can't anchor one — same
    // pattern as Theme… below).
    CommandGroup(before: .systemServices) {
      // App menu: symlink the bundled CLI into the user's PATH (like VS Code's "Install 'code'
      // command"). Prompts for admin only if the target dir needs it. See CommandLineInstaller.
      Button("Install ‘workroom’ Command in PATH…") {
        Task { await CommandLineInstaller.runFromMenu() }
      }
      Button("Keyboard Shortcuts…") {
        NotificationCenter.default.post(name: .showKeyboardShortcuts, object: nil)
      }
    }

    // Sit the quit-confirmation toggle just above Quit (default on): `.appVisibility` is the
    // Hide/Show All group, the last thing before Quit, so `after:` lands between it and Quit. A
    // divider separates it from that group; mirrored by the Settings checkbox.
    CommandGroup(after: .appVisibility) {
      Divider()
      Toggle("Confirm Before Quitting", isOn: $confirmOnQuit)
    }

    // Replace the default "Show/Hide Sidebar" with a clearer "Projects" label — it's the projects
    // sidebar. A `Toggle` (not a plain `toggleSidebar` Button) so the menu shows a checkmark when the
    // sidebar is visible; it binds `store.sidebarVisible`, which drives the split view's column
    // visibility. Keeps the conventional ⌃⌘S shortcut.
    CommandGroup(replacing: .sidebar) {
      Toggle("Projects", isOn: storeFlag(\.sidebarVisible))
        .keyboardShortcut("s", modifiers: [.command, .control])

/// Keeps the selected workroom's local VCS status live (without polling) by watching its directory
/// for filesystem changes (issue #24 follow-up). Retargeted on selection; see
/// `updateSelectedWorkroomWatch` / `handleWorkroomFileChange`.
lazy var workroomFileWatcher = WorkroomFileWatcher { [weak self] paths in
  self?.handleWorkroomFileChange(paths)
}
/// The watcher's local-refresh task — cancel-and-replace so the latest filesystem change wins and
/// at most one probe from THIS lane is in flight. That alone does NOT serialize jj snapshots
/// overall: the sweep and the selection-refresh lanes (`AppStore+WorkroomStatus.swift`) can still
/// reach `resolveLocal` concurrently with this one for the same project. Cross-lane (and
/// cross-window) jj snapshot ordering is `JJSnapshotGate`'s job, threaded through
/// `WorkroomStatusResolver.resolveLocal`'s `projectRoot` parameter.
var watchRefreshTask: Task<Void, Never>?
/// Live root branch/bookmark labels: one filesystem watcher per project, pointed at its VCS
/// metadata dir (`.git` / `.jj`). A branch switch or bookmark move in the root terminal updates
/// the sidebar label immediately, instead of waiting for the throttled on-focus reload. Keyed per
/// project (unlike the single `workroomFileWatcher`) because root labels are global, not
/// selection-scoped. The watch is naturally quiet — working-tree edits don't touch `.git`/`.jj`,
/// only VCS operations do — and resolution is read-only + deduped, so it can't loop or churn.
private var rootBranchWatchers: [Project.ID: WorkroomFileWatcher] = [:]
/// Per-project re-resolve task (cancel-and-replace) so a burst of metadata writes resolves once.
private var rootBranchRefreshTasks: [Project.ID: Task<Void, Never>] = [:]
/// When the project list was last loaded — used to throttle the on-focus refresh.
private var lastLoadAt: Date = .distantPast
/// The selection persisted from a previous launch (issue #14), applied once on the first
/// successful load (see `apply`). Consumed there so a later refresh can't resurrect it.
///
/// Seeded from `Defaults[.sidebarSelection]`, and overwritten by a claimed session's own selection
/// (issue #46) — the session owns selection per window; the Defaults key is the single-slot
/// cold-start fallback. Internal rather than private so `AppStore+Session` can do that.
var pendingRestoreSelection: TerminalTarget.ID?
/// This window's claimed saved session (issue #46), consumed at the end of `apply`.
var pendingSessionRestore: WindowSession?
/// One-shot guard: `WindowAccessor` can resolve the same window more than once, and a claim must
/// never be taken twice.
var didClaimSession = false
/// Whether this window may adopt a saved session (issue #46) — the launch window and each sibling
/// reopened from the session, but never a ⌘N window, which always starts blank.
var claimsSavedSession = false
/// UI-test fixture mode only: whether this window auto-selects the fixture workroom. True for the
/// launch window, false for a ⌘N window so it stays blank — the fixture analogue of clearing
/// `pendingRestoreSelection` on the real path (issue #70).
private var fixtureAutoSelect = true

/// Production builds one store per window (issue #70), each sharing `ProjectStore.shared`; tests
/// build an isolated `AppStore()` (own fresh `ProjectStore`), inject `projects`, and drive the real
/// recording/navigation paths. `init` does no CLI work (only `bootstrap()`/`load()` do).
init(
  projectStore: ProjectStore? = nil, cli: WorkroomCLIProtocol? = nil,
  commitHistory: HistoryModel? = nil, remoteState: RemoteStateModel? = nil
) {
  // Default to a fresh, isolated store (so `AppStore()` in tests never touches the singleton);
  // production passes `.shared`. Constructed here in the main-actor init body, not as a default
  // argument (default args are evaluated nonisolated, which can't call a @MainActor initializer).
  let store = projectStore ?? ProjectStore()
  self.projectStore = store
  self.cli = cli ?? WorkroomCLI.shared
  // `commitHistory` is assigned here (not inline) for the same @MainActor reason: a test injects a
  // stub to observe the live-refresh triggers; production/fixture keep the default.
  self.commitHistory =
    commitHistory
    ?? (UITestFixture.isActive
      ? HistoryModel(resolve: { _ in UITestFixture.vcsProvider })
      : HistoryModel())
  // Same seam as `commitHistory` above: fixture mode serves seeded state and records actions instead
  // of running git/jj, since the fixture's paths aren't real repos. Auto-fetch is disabled outright —
  // an automatic action would race whatever the test is asserting.
  self.remoteState =
    remoteState
    ?? (UITestFixture.isActive
      ? RemoteStateModel(
        makeWriter: { _ in FixtureVCSWriter() }, debounce: 0, ttl: 0,
        autoFetchInterval: .greatestFiniteMagnitude)
      : RemoteStateModel())
  // Re-publish the shared project store's changes so views and menus observing THIS store
  // re-render when the proxied `projects` / `rootRefs` / `workroomStatuses` / … change (issue #70).
  projectStoreObservation = store.objectWillChange.sink { [weak self] _ in
    self?.objectWillChange.send()
  }
  // Any pane change marks the saved session dirty (issue #46). `objectWillChange` fires BEFORE the
  // mutation, so the coordinator must always schedule a capture — never take one inline here.
  sessionObservation = terminals.objectWillChange.sink { [weak self] _ in
    self?.markSessionDirty()
  }
  // Wired post-init (the `workroomFileWatcher` idiom) so `RemoteStateModel` needs no `AppStore` to be
  // unit-tested. `onBranchResolved` makes this model the single writer of the shared branch cache
  // every branch-showing surface reads through `branchName(for:)`.
  self.remoteState.onBranchResolved = { [weak self] sid, name in
    self?.setResolvedBranchName(name, for: sid)
  }
  self.remoteState.onDidMutate = { [weak self] action, sid in
    self?.handleRemoteMutation(action, on: sid)
  }
  // Only the store can name a target, and the model needs the name to attribute a failure that
  // outlived the selection it started from.
  self.remoteState.describeTarget = { [weak self] sid in self?.label(for: sid).full }
  pendingRestoreSelection = Defaults[.sidebarSelection]
  // Route each terminal's activity (OSC/bell) through the notification spine, gated on
  // focus, and raise a native banner only when the app is backgrounded.
  terminals.activityHandler = { [weak self] targetID, tabID, activity in
    self?.handleActivity(targetID: targetID, tabID: tabID, activity: activity)
  }
  // Record each focused-tab change for back/forward history (issue #26), unless we're replaying.
  terminals.onFocusChange = { [weak self] _, tabID in
    guard let self else { return }
    // Quick-switcher recency (issue #132) — recorded before the history guard below, for the same
    // reason as the `selectedTargetID` didSet: the switcher's own commit runs under
    // `isNavigatingHistory`.
    SwitcherRecency.shared.recordPane(tabID)
    // The in-file find is tied to the focused file pane (the model is shared across panes). Any
    // focused-tab change ends that session: close it so ⌘G can't step a hidden find from a
    // terminal/diff pane, and the bar doesn't reappear pre-filled on the next file (review).
    if self.fileFind.isOpen { self.fileFind.close() }
    // A focus change includes a freshly-added tab appearing → re-enable the inspector.
    self.refreshSelectionHasTabs()
    guard !self.isNavigatingHistory else { return }
    self.recordCurrentLocation()
  }
  // A tab's content changed underneath an unmoved focus (the shared preview tab being retargeted, or
  // a file selected inside a commit). `onFocusChange` cannot see either, which is why browsing the
